    return <p>Error</p>;
  }
  // ...
```

Instead, wrap the component in an Error Boundary:

```jsx
function Albums({ albumsPromise }) {
  // ✅ Call `use` without try-catch
  const albums = use(albumsPromise);
  // ...
```

